      var _myDisc = parseFloat((document.getElementById('pDealDiscount') || {}).value) || 0;
      var _myRate = parseFloat((document.getElementById('pDealRate') || {}).value) || DAY_RATE;
      var _myAnnual = totalDays * _myRate;
      var _myDiscounted = _myAnnual * (1 - _myDisc / 100);
