      var _ou = chain.upsert.bind(chain);
      chain.upsert = function(d) { if (Array.isArray(d)) d = d.map(function(r){return Object.assign({tenant_id:TENANT_ID},r);}); else if (d && typeof d === 'object') d = Object.assign({tenant_id:TENANT_ID},d); return _ou(d); };
      var _os = chain.select.bind(chain);
