var _currentFaviconHref = '';
function applyFavicon(dataUrl) {

  if (!dataUrl) return;

  if (dataUrl === _currentFaviconHref) return;
  _currentFaviconHref = dataUrl;

  var existing = document.getElementById('faviconLink');
  if (existing) {
    if (dataUrl.indexOf('image/svg') !== -1) existing.type = 'image/svg+xml';
    else if (dataUrl.indexOf('image/x-icon') !== -1 || dataUrl.indexOf('image/vnd.microsoft.icon') !== -1) existing.type = 'image/x-icon';
    else existing.type = 'image/png';
    existing.href = dataUrl;
    return;
  }

  var link = document.createElement('link');
  link.rel = 'icon';
  link.id = 'faviconLink';
  if (dataUrl.indexOf('image/svg') !== -1) link.type = 'image/svg+xml';
  else if (dataUrl.indexOf('image/x-icon') !== -1 || dataUrl.indexOf('image/vnd.microsoft.icon') !== -1) link.type = 'image/x-icon';
  else link.type = 'image/png';
  link.href = dataUrl;
  document.head.appendChild(link);
}
