var _ASSESS_PAGES = ['assessments', 'assessment-detail', 'finding-detail', 'retests'];
function canAccessPage(page) {
  if (!S.profile) return page === 'dashboard';

  if (_PORTAL_PAGES.indexOf(page) < 0) return false;

  if (page === 'settings') return S.profile.role === 'admin';

  if (page === 'users' || page === 'subscription') return canManage();

  if (page === 'contractors') return canManage() && contractorsEnabled();

  if (page === 'dashboard' && !dashboardEnabled()) return false;
  if ((page === 'proposals' || page === 'signatures') && !proposalsEnabled()) return false;

  if (_ASSESS_PAGES.indexOf(page) > -1 && !assessmentsEnabled()) return false;
  if (page === 'library' && !libraryEnabled()) return false;
  if (page === 'invoices' && !invoicesEnabled()) return false;
  if (page === 'feedback' && !feedbackEnabled()) return false;
  if (page === 'meet-calendar' && !meetCalendarEnabled()) return false;
  if ((page === 'calendar' || page === 'assign') && !testingCalendarEnabled()) return false;

  if ((page === 'calendar' || page === 'assign' || page === 'qa' || page === 'qa-review') && !assessmentsEnabled()) return false;
  if ((page === 'qa' || page === 'qa-review') && !qaEnabled()) return false;

  if (page === 'all-findings' && !_findingsAreaOn()) return false;
  if (page === 'findings' && S.profile.role === 'client'
      && !(_clientAssessmentsOn(S.profile.client_id) || scanningEnabled())) return false;
  if (page === 'meetings' && !meetingsEnabled()) return false;
  if (page === 'contacts' && !contactsEnabled()) return false;
  if ((page === 'scans' || page === 'scan-detail') && !scanningEnabled()) return false;

  if ((page === 'scans' || page === 'scan-detail') && S.profile.role === 'client'
      && !(typeof scanningEnabled === 'function' && scanningEnabled())) return false;
  if ((page === 'scans' || page === 'scan-detail') && S.profile.role === 'client'
      && !(typeof _selfScanModuleOn === 'function' && _selfScanModuleOn())) return false;
  if ((page === 'scans' || page === 'scan-detail') && S.profile.role === 'client'
      && !(typeof _ssCfg === 'function' && _ssCfg().who !== 'staff')) return false;

  if ((page === 'scans' || page === 'scan-detail') && S.profile.role === 'client') {
    var _myC = (S.data.clients || []).find(function (x) {
      return x.id === (S.profile && S.profile.client_id);
    });

    if (_myC && _myC.self_scan_enabled === false) return false;
  }

  if (S.profile.role === 'client' && _ASSESS_PAGES.indexOf(page) > -1) {
    if (!_clientAssessmentsOn(S.profile && S.profile.client_id)) return false;
  }

  if (isContractor()) {
    var _contractorBlocked = ['contacts', 'invoices', 'signatures', 'meet-calendar'];
    if (_contractorBlocked.indexOf(page) >= 0) return false;

    if (page === 'library' && !contractorsLibraryOn()) return false;
  }

  if (isSales() || isMarketing()) {
    var _techPages = ['calendar', 'assign', 'qa', 'qa-review', 'library', 'retests', 'scans', 'scan-detail', 'all-findings',
      'assessments', 'assessment-detail', 'finding-detail', 'findings', 'report-builder'];
    if (_techPages.indexOf(page) >= 0) return false;
  }
  return true;
}
