async function _doFindingsExport(assessmentId, phaseFilter, mode) {
  var selectedCols = Array.from(document.querySelectorAll('.exp-col:checked')).map(function(cb) { return cb.dataset.key; });
  if (!selectedCols.length) { toast('Select at least one column', 'error'); return; }
  var includeSummary = !!(document.getElementById('exp_summary') && document.getElementById('exp_summary').checked);
  var includeEvidence = !!(document.getElementById('exp_evidence') && document.getElementById('exp_evidence').checked);
  _saveExportPrefs({ columns: selectedCols, format: 'xlsx', includeSummary: includeSummary, includeEvidence: includeEvidence });
  closeM();

  var a = (S.data.assessments || []).find(function(x) { return x.id === assessmentId; });
  if (!a) { toast('Assessment not found', 'error'); return; }
  var isClientUser = !!(S.profile && S.profile.role === 'client');

  var activeCols = selectedCols.map(function(k) { return _allFindingExportColumns().find(function(c) { return c.key === k; }); }).filter(Boolean);
  if (!activeCols.length) { toast('No columns selected', 'error'); return; }

  _showLoading();
  try {
    var ExcelJS = await _ensureExcelJs();
    if (!ExcelJS) { toast('Excel library failed to load', 'error'); return; }

    var figCounter = _makeFigCounter();

    _exportImageCache = {};

    var figureCatalog = [];

    var workbook = new ExcelJS.Workbook();
    workbook.creator = 'Pental';
    workbook.created = new Date();

    if (mode === 'multi') {

      var rawPhases = _getPhases(a) || [];
      if (!rawPhases.length) rawPhases = [{ type: 'Findings' }];
      var allowed = (S.data.findings || []).filter(function(f) { return f.assessment_id === assessmentId; });
      if (isClientUser) allowed = allowed.filter(function(f) { return f.client_visible === true; });
      if (isContractor()) allowed = allowed.filter(function(f) { return !f.lead_id || f.lead_id === S.profile.id || f.created_by === S.profile.id; });
      allowed.sort(_findingCmp);

      var phaseGroups = rawPhases.map(function(ph, idx) {
        var label = ph.type || ('Phase ' + (idx + 1));
        return { label: label, normKey: _normPhase(label), findings: [] };
      });
      var unphased = [];
      allowed.forEach(function(f) {
        var fNorm = _normPhase(f.phase);
        if (!fNorm) { unphased.push(f); return; }
        var bucket = phaseGroups.find(function(g) { return g.normKey === fNorm; });
        if (bucket) bucket.findings.push(f);
        else unphased.push(f);
      });

      if (includeSummary) _buildSummarySheet(workbook, a, phaseGroups, unphased);

      var totalRows = 0;
      for (var pi = 0; pi < phaseGroups.length; pi++) {
        var g = phaseGroups[pi];
        if (!g.findings.length) continue;
        await _buildFindingsSheet(workbook, g.label, g.findings, a, activeCols, isClientUser, figCounter, figureCatalog);
        totalRows += g.findings.length;
      }
      if (unphased.length) {
        await _buildFindingsSheet(workbook, 'Other', unphased, a, activeCols, isClientUser, figCounter, figureCatalog);
        totalRows += unphased.length;
      }

      if (includeEvidence && figureCatalog.length) {
        await _buildEvidenceSheet(workbook, figureCatalog);
      }

      if (!totalRows && !includeSummary) { toast('No findings to export', 'info'); return; }
      var buffer = await workbook.xlsx.writeBuffer();
      _downloadBlob(buffer, _findingsFilename(assessmentId, '', 'findings_xlsx_multi', 'xlsx'));
      var tabs = workbook.worksheets.length;
      toast('Exported ' + totalRows + ' finding' + (totalRows === 1 ? '' : 's') + ' across ' + tabs + ' tab' + (tabs === 1 ? '' : 's'), 'success');
      return;
    }

    var gathered = _gatherFindingsForExport(assessmentId, phaseFilter);
    if (!gathered || !gathered.findings.length) { toast('No findings to export', 'info'); return; }

    if (includeSummary) {
      var summaryLabel = phaseFilter || 'All findings';
      _buildSummarySheet(workbook, a, [{ label: summaryLabel, normKey: _normPhase(summaryLabel), findings: gathered.findings }], []);
    }

    var sheetTitle = phaseFilter || 'Findings';
    await _buildFindingsSheet(workbook, sheetTitle, gathered.findings, a, activeCols, isClientUser, figCounter, figureCatalog);

    if (includeEvidence && figureCatalog.length) {
      await _buildEvidenceSheet(workbook, figureCatalog);
    }

    var buf = await workbook.xlsx.writeBuffer();
    _downloadBlob(buf, _findingsFilename(assessmentId, phaseFilter || '', 'findings_xlsx', 'xlsx'));
    toast('Exported ' + gathered.findings.length + ' finding' + (gathered.findings.length === 1 ? '' : 's'), 'success');
  } catch(e) {
    console.error('Export failed:', e);
    toast('Export failed: ' + (e && e.message ? e.message : 'unknown error'), 'error');
  } finally {
    _hideLoading();
  }
}
function _downloadBlob(buffer, filename) {
  var blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  var url = URL.createObjectURL(blob);
  var aEl = document.createElement('a');
  aEl.href = url;
  aEl.download = filename;
  aEl.click();
  setTimeout(function() { URL.revokeObjectURL(url); }, 100);
}
