async function _loadAutomationLastRun() {
  var el = document.getElementById('autoLastRun');
  if (!el) return;
  var healthP = _scheduleHealth();
  try {
    var r = await supabaseClient.from('_pental_rpc_audit_log').select('at')
      .eq('op', 'rpc_automation_due').eq('auth_mode', 'signed').eq('result', 'ok')
      .order('at', { ascending: false }).limit(1);
    var health = await healthP;
    if (r.error) { el.textContent = ''; return; }
    var row = r.data && r.data[0];
    el.style.color = '';
    if (health && health.deployed && health.cron_secret === false) {
      el.style.color = 'var(--yellow)';
      el.textContent = 'The schedule cannot run on its own: the portal’s server has no CRON_SECRET, so every 15-minute pass is refused before it starts.'
        + ' That is set on Pental’s side (CRON_SECRET on the portal’s Vercel project, then a redeploy).'
        + ' Until then Run now does what is due, and so does saving an assessment.'
        + (row ? ' It last ran on its own ' + fmtDateTime(row.at) + '.' : '');
      return;
    }
    if (!row) {
      el.textContent = 'The schedule has not reached your database yet. After a database update the first pass is at most 15 minutes away.';
      return;
    }
    var mins = Math.round((Date.now() - new Date(row.at).getTime()) / 60000);
    el.textContent = 'The schedule last ran ' + fmtDateTime(row.at) + '.'
      + (mins > 30 ? ' It runs every 15 minutes, so that is later than it should be. Contact Pental support if it stays that way.' : '');
  } catch (e) { el.textContent = ''; }
}
