async function deleteUser(userId) {
  if (!supabaseClient) { toast("Not connected", "error"); return; }

  var targetUser = (S.data.users || []).find(function(u) { return u.id === userId; });
  if (!targetUser) { toast('User not found', 'error'); return; }
  if (!canModifyUser(targetUser)) {

    toast(
      isAccountOwner(targetUser.id)
        ? _rpOwnerSays('stays')
        : (targetUser.role === 'admin'
          ? _rpOwnerSays('remove')
          : 'You cannot delete users with equal or higher roles'),
      'error');
    return;
  }

  showConfirm('Delete this user? This cannot be undone.', 'Delete User', async function() {
    try {
      var result = await adminApi('delete_user', { user_id: userId }, { raw: true });
      if (!result) return;
      if (result._ok) {
        toast(result.message || 'User deleted', 'success');
        await refreshAndStay();
        return;
      }

      if (String(result.reason || '') === 'rank' && isAccountOwner()
        && targetUser.role === 'admin') {
        toast('Your portal is on a newer version than your database. Run the setup SQL from the '
          + 'update banner on your dashboard, then try again \u2014 removing another administrator '
          + 'is a rule your database enforces, and yours still has the older one.', 'error');
        return;
      }

      if (result.can_force) {
        if (await confirmAsync(result.error + ' Continue?', { title: 'Also remove those records?', confirmText: 'Delete anyway', variant: 'danger' })) {
          var forced = await adminApi('delete_user', { user_id: userId, force: true }, { raw: true });
          if (forced && forced._ok) { toast(forced.message || 'User deleted', 'success'); await refreshAndStay(); }
          else if (forced) toast(forced.error || 'Delete failed', 'error');
        }
        return;
      }
      toast(result.error || 'Delete failed', 'error');
    } catch (e) {
      toast('Error: ' + e.message, 'error');
    }
  });
}
