  try { sessionStorage.removeItem('pental_tenant'); } catch(e) {}

  try { localStorage.removeItem('pental_mfa_verified'); } catch(e) {}
  try {
    window._loginEmail = null;
    window._pendingMagicLink = null;
    window._pendingMagicEmail = null;
    window._codeLoginInProgress = false;
    window._verifyingCode = false;
    window._mfaAccessToken = null;
  } catch(e) {}
  try { await supabaseClient.auth.signOut(); } catch(e) {}

  try {
    Object.keys(localStorage).forEach(function(k) {
      if (k.indexOf('pental-portal-') === 0 ||
          (k.indexOf('sb-') === 0 && k.indexOf('-auth-token') !== -1)) {
        localStorage.removeItem(k);
      }
    });
  } catch(e) {}
  S.user = null;
  S.profile = null;
  S.data = { clients: [], assessments: [], findings: [], proposals: [], invoices: [], kb: [], users: [], clientUsers: [], feedback: [], files: [], assessment_comments: [], qa_comments: [], contractor_payments: [], meetings: [], meeting_attendees: [], contact_requests: [], settings: {} };
  _syncReset();
