    try {
      label = (await promptAsync('So you can tell your keys apart later.', { title: 'Name this security key', value: 'Security key', confirmText: 'Register', required: false })) || 'Security key';
    } catch(e) { label = 'Security key'; }
    label = String(label).slice(0, 80);

    var compRes = await tenantFetch('/api/admin', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
      body: JSON.stringify({ action: 'mfa_webauthn_enroll_complete', attestation: attestation, label: label, transports: masterTransports }),
    });
    var compData = await compRes.json();
    if (!compRes.ok || !compData.success) {
      toast(compData.error || 'Could not store key', 'error');
      return;
    }
    try { await supabaseClient.auth.refreshSession(); } catch(e) {}
    await _refreshSecurityCard();

    var listEl = document.getElementById('securityWebAuthnList');
