async function submitRemoveWebAuthnKey(id, credentialId) {
  var btn = document.getElementById('removeKeyBtn');
  var errEl = document.getElementById('removeKeyError');
  if (btn) { btn.disabled = true; btn.textContent = 'Waiting for your key...'; }
  if (errEl) errEl.style.display = 'none';

  try {
    var isByo = !!(window.TENANT_INFO && window.TENANT_INFO.is_byo);

    if (isByo) {

      var canonical = {
        op: 'mfa_assert',
        nonce: _bufToB64u(crypto.getRandomValues(new Uint8Array(24))),
        exp: Math.floor(Date.now() / 1000) + 120,
        purpose: 'remove_key',
        target_credential_id: credentialId,
      };
      var canonicalText = JSON.stringify(canonical);
      var challengeB64u = await _sha256B64u(canonicalText);
      var challengeBytes = new Uint8Array(_b64uToAb(challengeB64u));

      var rpId = window.location.hostname;

      var byoDelTransports = null;
      try {
        var trRes = await supabaseClient.from('webauthn_credentials')
          .select('transports')
          .eq('credential_id', credentialId)
          .limit(1)
          .maybeSingle();
        if (trRes && trRes.data && Array.isArray(trRes.data.transports) && trRes.data.transports.length) {
          byoDelTransports = trRes.data.transports;
        }
      } catch (e) {}
      var byoDelEntry = { type: 'public-key', id: _b64uToAb(credentialId) };
      if (byoDelTransports) byoDelEntry.transports = byoDelTransports;
      var assertion = await navigator.credentials.get({
        publicKey: {
          challenge: challengeBytes,
          rpId: rpId,
          allowCredentials: [byoDelEntry],
          userVerification: 'preferred',
          timeout: 60000,
        },
      });
      if (!assertion) throw new Error('No assertion');

      if (_abToB64u(assertion.rawId) !== credentialId) {
        throw new Error('Assertion key does not match the key being removed');
      }

      var assertionData = {
        credential_id: _abToB64u(assertion.rawId),
        client_data_json: _abToB64u(assertion.response.clientDataJSON),
        authenticator_data: _abToB64u(assertion.response.authenticatorData),
        signature: _abToB64u(assertion.response.signature),
        expected_origin: window.location.origin,
      };
      var applyRes = await supabaseClient.rpc('rpc_apply_signed_settings', {
        p_payload_canonical: canonicalText,
        p_assertion: assertionData,
      });
      if (applyRes.error) throw new Error(applyRes.error.message || 'Verification failed');

      try { await supabaseClient.auth.refreshSession(); } catch(e) {}

      var byoDel = await supabaseClient.from('webauthn_credentials').delete().eq('id', id);
      if (byoDel.error) throw new Error(byoDel.error.message || 'Could not remove key');
    } else {

      var token = await _getMfaToken();

      var optsRes = await tenantFetch('/api/admin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
        body: JSON.stringify({ action: 'mfa_webauthn_verify_options' }),
      });
      var optsData = await optsRes.json();
      if (!optsRes.ok) throw new Error(optsData.error || 'Could not get challenge');
      var pkOptions = optsData.options;
      pkOptions.challenge = _b64uToBuf(pkOptions.challenge);

      var matchEntry = null;
      if (Array.isArray(pkOptions.allowCredentials)) {
        for (var ai = 0; ai < pkOptions.allowCredentials.length; ai++) {
          if (pkOptions.allowCredentials[ai].id === credentialId) {
            matchEntry = pkOptions.allowCredentials[ai];
            break;
          }
        }
      }
      var pinned = { type: 'public-key', id: _b64uToBuf(credentialId) };
      if (matchEntry && Array.isArray(matchEntry.transports) && matchEntry.transports.length) {
        pinned.transports = matchEntry.transports;
      }
      pkOptions.allowCredentials = [pinned];

      var assertionM = await navigator.credentials.get({ publicKey: pkOptions });
      if (!assertionM) throw new Error('No assertion');
      if (assertionM.id !== credentialId) {
        throw new Error('Assertion key does not match the key being removed');
      }
      var assertionJson = {
        id: assertionM.id,
        rawId: _bufToB64u(assertionM.rawId),
        type: assertionM.type,
        response: {
          clientDataJSON: _bufToB64u(assertionM.response.clientDataJSON),
          authenticatorData: _bufToB64u(assertionM.response.authenticatorData),
          signature: _bufToB64u(assertionM.response.signature),
          userHandle: assertionM.response.userHandle ? _bufToB64u(assertionM.response.userHandle) : null,
        },
        clientExtensionResults: assertionM.getClientExtensionResults ? assertionM.getClientExtensionResults() : {},
      };
      var verRes = await tenantFetch('/api/admin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
        body: JSON.stringify({ action: 'mfa_webauthn_verify', assertion: assertionJson }),
      });
      var verData = await verRes.json();
      if (!verRes.ok || !verData.success) throw new Error(verData.error || 'Verification failed');

      try { await supabaseClient.auth.refreshSession(); } catch(e) {}
      var delRes = await supabaseClient.from('webauthn_credentials_master').delete().eq('id', id);
      if (delRes.error) throw new Error(delRes.error.message || 'Could not remove key');
    }

    closeM();
    await _refreshSecurityCard();
    await loadAndShowWebAuthnList();
    toast('Security key removed', 'success');
  } catch (e) {
    var msg = (e && e.message) || 'Removal failed';
    if (msg.indexOf('NotAllowed') >= 0) msg = 'Removal cancelled';
    if (errEl) { errEl.textContent = msg; errEl.style.display = 'block'; }
    if (btn) { btn.disabled = false; btn.textContent = 'Tap key and remove'; }
  }
}
