async function verifyMfaCode() {
  if (await _refuseIfSessionOver()) return;
  var code = (document.getElementById('mfaTotpInput') || {}).value || '';
  if (code.length !== 6) return;
  var btn = document.getElementById('mfaVerifyBtn');
  var errEl = document.getElementById('mfaError');
  if (btn) { btn.disabled = true; btn.textContent = 'Verifying...'; }
  if (errEl) errEl.style.display = 'none';

  window._codeLoginInProgress = true;

  try {

    var token = await _getMfaToken();
    if (!token) {
      window._codeLoginInProgress = false;
      if (errEl) { errEl.textContent = 'Session expired. Please refresh.'; errEl.style.display = 'block'; }
      if (btn) { btn.disabled = false; btn.textContent = 'Sign in'; }
      return;
    }

    var res = await _totpDirect('totp_verify', { email: _mfaEmail(), totp_code: code }, _nativeFetch);
    var data = await res.json();
    if (res.ok && data.success) {
      _mfaVerifiedNow('totp');

      S._mfaScreenShown = false;

      window._codeLoginInProgress = false;
      window._verifyingCode = false;
      window._mfaAccessToken = null;
      if (window._mfaFlagTimer) { clearTimeout(window._mfaFlagTimer); window._mfaFlagTimer = null; }
      S._mfaStatusCache = null;

      try { await supabaseClient.auth.refreshSession(); } catch(e) { console.warn('[MFA] post-verify refresh failed:', e && e.message); }
      await loadProfile();

      if (await _mfaResumeEnrolment()) return;
      _suppressRender = true;
      if (S.profile) { _hydrateShellCache(); await loadAllData(); applyPendingRestore(); _setupRealtime(); startSessionTimeout(); registerActiveSession(); reportUsage(); }
      _suppressRender = false;
      window._showWelcomeToast = true;
      _fadeToApp();
    } else {
      if (res.status === 429) {

        if (errEl) { errEl.textContent = data.error || 'Too many attempts. Please wait.'; errEl.style.display = 'block'; }
        if (btn) { btn.disabled = true; btn.textContent = 'Locked'; }
        var inp = document.getElementById('mfaTotpInput');
        if (inp) { inp.disabled = true; inp.value = ''; }

        setTimeout(function() {
          var _b = document.getElementById('mfaVerifyBtn');
          var _i = document.getElementById('mfaTotpInput');
          if (_b) { _b.disabled = false; _b.textContent = 'Sign in'; }
          if (_i) { _i.disabled = false; _i.focus(); }
        }, 60000);
      } else {
        if (errEl) { errEl.textContent = data.error || 'Invalid code'; errEl.style.display = 'block'; }
        if (btn) { btn.disabled = false; btn.textContent = 'Sign in'; }
        var inp = document.getElementById('mfaTotpInput');
        if (inp) { inp.value = ''; inp.focus(); }
      }
    }
  } catch(e) {
    if (errEl) { errEl.textContent = 'Network error'; errEl.style.display = 'block'; }
    if (btn) { btn.disabled = false; btn.textContent = 'Sign in'; }
  }
}
async function _verifyMagicToken(email, token) {
  _showLoading();
  try {
    var res = await tenantFetch('/api/auth-code', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'verify', email: email, code: token })
    });
    var data = await res.json();
    if (!res.ok || !data.access_token) {
      _hideLoading();

      render();
      setTimeout(function() {
        var errEl = document.getElementById('loginError');
        if (errEl) { errEl.textContent = 'Sign-in link expired or already used. Please request a new code.'; errEl.style.display = 'block'; }
      }, 100);
      return;
    }
    window._codeLoginInProgress = true;
    var sessData = _forceSetSession(data.access_token, data.refresh_token);
    if (!sessData || !sessData.session) {
      window._codeLoginInProgress = false;
      _hideLoading();
      render();
      return;
    }
    S.user = sessData.session.user;
    window._mfaAccessToken = sessData.session.access_token;
    startSessionKeepalive();
    restoreNavState();
    _hideLoading();
    await loadProfile();
    if (S.profile) {

      if (!S._mfaPolicy) { try { S._mfaPolicy = await _loadMfaPolicy(); } catch (e) {} }
      var _needSetup = _mfaEnrolmentIncomplete(S.profile, S._mfaPolicy);

      var _mfaStale = _mfaNewSession();
      S._mfaProfile = S.profile;
      _suppressRender = true;
      document.body.classList.add('loaded');

      if (_mfaStale && _mfaHasEnrolled(S.profile)) _showMfaVerify('L26482');
      else renderMfaSetup();

      return;
    }
    _suppressRender = false;
    window._codeLoginInProgress = false;
    window._showWelcomeToast = true;
    _fadeToApp();
  } catch(e) {
    console.error('Magic link error:', e);
    _hideLoading();
    render();
  }
}
function _fadeToApp() {
  var loginPage = document.querySelector('.login-page');
  if (!loginPage) { render(); return; }
  loginPage.style.transition = 'opacity 0.3s ease';
  loginPage.style.opacity = '0';
  setTimeout(function() {
    window._appFadeIn = true;
    render();
  }, 300);
}
