function _getUnreadComments() {
  var myId = S.profile ? S.profile.id : '';
  if (!myId) return [];
  var role = S.profile ? S.profile.role : '';
  var isClient = role === 'client';
  var clientId = isClient ? S.profile.client_id : null;
  var readIds = _getReadNotifIds();
  var assessments = S.data.assessments || [];

  var byId = {};
  for (var i = 0; i < assessments.length; i++) byId[assessments[i].id] = assessments[i];

  return (S.data.assessment_comments || []).filter(function(c) {

    if (c.user_id === myId) return false;

    if (readIds.indexOf(c.id) >= 0) return false;
    var a = byId[c.assessment_id];
    if (!a) return false;

    if (isClient) {

      if (a.client_id !== clientId) return false;
      if (c.client_visible === false) return false;
      return true;
    }

    return a.lead_id === myId;
  });
}
