async function _aiVerifyUrls(urls, signal) {
  urls = (urls || []).filter(function (u) { return typeof u === 'string' && /^https?:\/\//i.test(u.trim()); }).map(function (u) { return u.trim(); });
  if (!urls.length) return { valid: [], dead: [] };
  try {
    var resp = await tenantFetch('/api/utils?fn=check-urls', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ urls: urls }),
      signal: signal || undefined
    });
    if (!resp.ok) return { valid: urls, dead: [] };
    var data = await resp.json();
    var valid = [], dead = [];
    (data.results || []).forEach(function (r) { if (r.valid) valid.push(r.url); else dead.push(r.url); });
    return { valid: valid, dead: dead };
  } catch (e) {

    if (signal && signal.aborted) throw e;
    return { valid: urls, dead: [] };
  }
}
