    var result;
    if (settings.id) {
      result = await _setPut(updates, settings.id, "id");
    } else {
      result = await supabaseClient.from('settings').insert(updates).select("id");
    }
    if (result.error) { _settingsSaveFailed(_errMsg(result.error)); return; }
    if (result.data && result.data[0]) settings.id = result.data[0].id;
    settings.pdf_templates = _pdfTpl;
    S.data.settings = settings;
