function _lcNotice(old, row) {
  if (!row || !S.profile || S.profile.role === 'client' || _lcWasMine(row.id)) return;
  var me = S.profile.id;
  var name = '“' + (row.name || 'A report') + '”';
  var go = function () { startQAReview(row.id); };
  var nowDel = _isDelivered(row);
  if (old.del && !nowDel) {
    if (row.lead_id === me || row.qa_assignee === me) {
      toast(name + ' was sent back to QA from delivery' + (row.qa_assignee === me ? ', with you reviewing it' : '') + '. Click to open the review.', 'info', 9000, go);
    }
    return;
  }
  if (!qaEnabled() || nowDel || row.qa_status === old.qa) return;
  if (row.qa_status === 'pending' && canManage() && row.lead_id !== me) {
    toast((getTesterName(row.lead_id) || 'A tester') + ' submitted ' + name + ' for QA. Click to review it.', 'info', 8000, go);
  } else if (row.qa_status === 'in_review' && old.qa === 'revision' && row.qa_assignee === me) {
    toast(name + ' is back with you for QA. Click to review it.', 'info', 8000, go);
  } else if (row.qa_status === 'revision' && row.lead_id === me) {
    toast('QA sent ' + name + ' back to you with changes. Click to open the review.', 'warning', 9000, go);
  } else if (row.qa_status === 'approved' && (row.lead_id === me || canManage())) {
    toast(name + ' is approved' + (_canDeliverNow(row) ? ' and ready to deliver' : '') + '. Click to open it.', 'success', 8000, go);
  }
}
