    xml += tag('{/phase_findings}');
    xml += tag('{/phases_data}');
    xml += tag('{/has_scope_phases}');
    xml += tag('{^has_scope_phases}');
    xml += h1('{heading_findings}', true);
    xml += tag('{#findings}');
    xml += finding(true);
    xml += tag('{/findings}');
    xml += tag('{/has_scope_phases}');
    xml += tag('{/show_findings}');

    xml += tag('{#show_retest_summary}');
    xml += tag('{#has_retest_summary}');
    xml += h1('{heading_retest_summary}', true);
    xml += rich('{retest_summary}');
    xml += tag('{/has_retest_summary}');
    xml += tag('{/show_retest_summary}');
    xml += tag('{#show_caveats}');
    xml += tag('{#has_caveats}');
    xml += h1('{heading_caveats}', true);
    xml += rich('{caveats}');
    xml += tag('{/has_caveats}');
    xml += tag('{/show_caveats}');
    xml += tag('{#has_notes}');
    xml += h1('Additional Notes');
    xml += rich('{notes}');
    xml += tag('{/has_notes}');
