    xml += para('{artifacts_text}');
    xml += tag('{/has_artifacts}');
    xml += tag('{/show_artifacts}');

    xml += tag('{#show_appendices}');
    xml += tag('{#has_appendices}');
    xml += h1('Appendices', true);
    xml += tag('{#appendix_methodology}');
    xml += tag('{#methodology_text}');
    xml += h2('{methodology_title}');
    xml += para('{methodology_text}');
    xml += tag('{#methodology_links}');
    xml += P(R('{methodology_links}', { color: ACC, size: 16 }), { after: 140 });
    xml += tag('{/methodology_links}');
    xml += tag('{/methodology_text}');
    xml += tag('{/appendix_methodology}');
    xml += tag('{#appendix_tc}');
    xml += tag('{#testing_conditions_text}');
    xml += h2('{testing_conditions_title}');
    xml += para('{testing_conditions_text}');
    xml += tag('{/testing_conditions_text}');
    xml += tag('{/appendix_tc}');
    xml += tag('{#appendix_qa}');
    xml += tag('{#qa_text}');
    xml += h2('{qa_title}');
    xml += para('{qa_text}');
    xml += tag('{/qa_text}');
    xml += tag('{/appendix_qa}');
