    body += '<label style="display:flex;justify-content:space-between;align-items:baseline;font-size:0.74rem;font-weight:700;color:var(--text);margin-bottom:0.2rem">' + esc(r.label) + (r.hint ? '<span style="font-weight:400;font-size:0.68rem;color:var(--gray)">' + esc(r.hint) + '</span>' : '') + '</label>';
