    if (!zip.file('word/styles.xml')) { toast('This template has no styles to map', 'error'); return; }
    var body = '<div style="font-size:0.8rem;color:var(--gray);margin-bottom:1rem;line-height:1.5">These are the styles the AI picked from <strong>' + esc(type) + '</strong> for generated content. Each is set to the detected style (flagged <em>AI pick</em>); change any you want and Save. Code rows list only this template\'s monospace styles; the others list all paragraph styles.</div>';
    body += _styleControlsHtml(zip, type);
    body += '<div style="font-size:0.72rem;color:var(--gray);margin-top:0.5rem">Use Reset to clear all choices and return to automatic detection.</div>';
    var footer = '<button class="btn btn-ghost" onclick="resetStyleMapping(\'' + type + '\')">Reset to auto</button><button class="btn btn-secondary" onclick="closeM()">Cancel</button><button class="btn btn-primary" onclick="saveStyleMapping(\'' + type + '\')">Save</button>';
    S.modal = { type: '_custom', html: '<div class="modal-overlay"><div class="modal-content" style="max-width:640px"><div class="modal-header"><span class="modal-title">Template Styles, ' + esc(type.charAt(0).toUpperCase() + type.slice(1)) + '</span><button class="modal-close" onclick="closeM()" title="Close">&times;</button></div><div class="modal-body">' + body + '</div><div class="modal-footer">' + footer + '</div></div></div>' };
    document.body.style.overflow = 'hidden';
