  h += '<div style="flex:1;min-width:0">';
  h += '<p style="font-size:0.88rem;line-height:1.55;color:var(--text);margin:0">' + esc(opts.message || '') + '</p>';
  if (opts.hint) h += '<p style="font-size:0.78rem;line-height:1.5;color:var(--gray);margin:0.6rem 0 0">' + esc(opts.hint) + '</p>';
  h += '</div></div></div>';
