async function forgetImportMap(format) {
  if (!format) return;
  if (!(await confirmAsync('The next ' + esc(format) + ' import will use the built-in field mapping again. '
    + 'Nothing already imported changes.', { title: 'Forget this mapping?', confirmText: 'Forget it' }))) return;
  _showLoading();
  try {
    var cur = (S.data.settings || {}).scan_import_maps;
    if (typeof cur === 'string') { try { cur = JSON.parse(cur); } catch (e) { cur = null; } }
    var next = {};
    Object.keys(cur || {}).forEach(function(k) { if (k !== format) next[k] = cur[k]; });
    var sid = (S.data.settings || {}).id;
    if (!sid) { toast('Settings are not loaded', 'error'); return; }
    var r = await _setPut({ scan_import_maps: next }, sid);
    if (r && r.error) { toast(_errMsg(r.error), 'error'); return; }
    S.data.settings.scan_import_maps = next;
    toast('Forgotten', 'success');
    render();
  } finally { _hideLoading(); }
}
window.forgetImportMap = forgetImportMap;
async function forgetImportSeverity(clientId) {
  var c = (S.data.clients || []).find(function(x) { return x.id === clientId; });
  if (!c) return;
  if (!(await confirmAsync('The next import for ' + esc(c.name || 'this client')
    + ' will keep everything in the file again, including informational findings. '
    + 'Nothing already imported changes.',
    { title: 'Forget this severity choice?', confirmText: 'Forget it' }))) return;
  _showLoading();
  try {
    var r = await supabaseClient.from('clients')
      .update({ scan_import_min_severity: null }).eq('id', clientId);
    if (r && r.error) { toast(_errMsg(r.error), 'error'); return; }
    c.scan_import_min_severity = null;
    toast('Forgotten', 'success');
    render();
  } finally { _hideLoading(); }
}
window.forgetImportSeverity = forgetImportSeverity;
