function _migSeverity(value, opts) {

  var v = String(value == null ? '' : value).replace(/<[^>]+>/g, ' ').toLowerCase()
    .replace(/[_\-]+/g, ' ').replace(/[^a-z0-9. ]+/g, ' ').replace(/\s+/g, ' ').trim();

  v = v.replace(/\s+(risk|severity|priority)$/, '');
  if (!v) return { severity: null, reason: 'empty' };

  var words = {
    critical: 'critical', crit: 'critical', 'very high': 'critical', urgent: 'critical', p1: 'critical', extreme: 'critical',
    high: 'high', p2: 'high', major: 'high',
    medium: 'medium', med: 'medium', moderate: 'medium', p3: 'medium',
    low: 'low', minor: 'low', p4: 'low', 'very low': 'low',
    info: 'info', informational: 'info', information: 'info', none: 'info', unclassified: 'info',
    note: 'info', 'best practice': 'info', suggestion: 'info', p5: 'info', observation: 'info',

    highest: 'critical', blocker: 'critical', lowest: 'info', trivial: 'info',
  };
  if (words[v]) return { severity: words[v], reason: 'word' };

  if (/^\d+(\.\d+)?$/.test(v)) {
    var n = parseFloat(v);

    if (n > 5) return { severity: n >= 9 ? 'critical' : n >= 7 ? 'high' : 'medium', reason: 'cvss' };
    if ((opts && opts.numbers) === 'cvss') {
      return { severity: n >= 4 ? 'medium' : n > 0 ? 'low' : 'info', reason: 'cvss' };
    }
    if ((opts && opts.numbers) === 'priority') {
      return { severity: ['critical', 'critical', 'high', 'medium', 'low', 'info'][Math.min(5, Math.round(n))], reason: 'priority' };
    }
    return { severity: null, reason: 'ambiguous_number' };
  }
  return { severity: null, reason: 'unknown' };
}
